// Wraps the OpenNext worker so Cloudflare's cron trigger can call the reminders route,
// the way Vercel Cron did (vercel.json). The route checks `Authorization: Bearer $CRON_SECRET`.
// @ts-expect-error generated by `opennextjs-cloudflare build`
import openNext from "./.open-next/worker.js";

interface Env {
  CRON_SECRET?: string;
  [key: string]: unknown;
}

export default {
  fetch: openNext.fetch,
  async scheduled(_event: unknown, env: Env, ctx: { waitUntil(p: Promise<unknown>): void }) {
    const req = new Request("https://app.watchguide.app/api/cron/reminders", {
      headers: { Authorization: `Bearer ${env.CRON_SECRET ?? ""}` },
    });
    ctx.waitUntil(openNext.fetch(req, env, ctx));
  },
};
